import ast; import sys; from pathlib import Path; from common.meta.extension.check_package_contract import check_single_package, discover_packages; REPO = Path(__file__).resolve().parents[2]; PORTFOLIO = REPO / 'apps/backend/src/portfolio'; _BACKEND_ROOT = str(REPO / 'apps' / 'backend'); sys.path.insert(0, _BACKEND_ROOT) if _BACKEND_ROOT not in sys.path else None
def _imported_modules(path: Path) -> set[str]: mods: set[str] = set(); [mods.add(node.module) if isinstance(node, ast.ImportFrom) and node.module else mods.update((a.name for a in node.names)) if isinstance(node, ast.Import) else None for node in ast.walk(ast.parse(path.read_text(encoding='utf-8')))]; return mods
def test_AC_portfolio_1_1_only_all_is_the_published_language(): import src.portfolio as portfolio_pkg; from common.portfolio.contract import CONTRACT; assert sorted(CONTRACT.interface) == sorted(portfolio_pkg.__all__); assert CONTRACT.name == 'portfolio'; assert CONTRACT.implementations['be'] == 'apps/backend/src/portfolio'
def test_AC_portfolio_1_2_converges_by_layer(): assert (PORTFOLIO / 'base' / 'errors.py').exists(); assert (PORTFOLIO / 'extension' / '__init__.py').exists(); assert (PORTFOLIO / 'data' / '__init__.py').exists()
def test_AC_portfolio_1_3_base_layer_is_pure():
    for py in (PORTFOLIO / 'base').rglob('*.py'):
        for mod in _imported_modules(py): assert not mod.startswith('src.portfolio.extension'), f'{py.name} imports extension ({mod}) from base/'; assert not mod.startswith('src.portfolio.data'), f'{py.name} imports data ({mod}) from base/'; assert not mod.startswith(('src.database', 'sqlalchemy')), f'{py.name} reaches the ORM from base/'; assert mod not in {'httpx', 'litellm', 'aiohttp'}, f'{py.name} reaches a network client from base/'
def test_AC_portfolio_1_4_package_contract_gate_passes(): packages = discover_packages(REPO); assert any((p.contract.name == 'portfolio' for p in packages)), 'portfolio not discovered'; ok, messages = check_single_package('portfolio', REPO); portfolio_errors = [m for m in messages if '[portfolio]' in m]; assert not portfolio_errors, f'gate violations for portfolio: {portfolio_errors}'; assert ok, 'check_package_contract failed for portfolio:\n' + '\n'.join(messages)
